\label{thm:closed}
For $w\in\mathbb C^+$ define
\begin{equation}\label{eq:H-def}
   H(w)
   :=
   -\frac1m\log\det G(w)
   +
   \frac12
   \operatorname{tr}_m\bigl(
      G(w)\eta(G(w))
   \bigr),
\end{equation}
where any holomorphic branch of $\log\det G$ on $\mathbb C^+$ may be
chosen.  Then
\begin{equation}\label{eq:H-logdet}
   \boxed{
   \operatorname{Re}H(w)
   =
   \log\Delta(S_a-w)
   }
   \qquad
   (w\in\mathbb C^+).
\end{equation}

Consequently, if $x\in\mathbb R$ is such that the boundary value
$
   G:=G(x+i0)
$
exists and is invertible, then
\begin{equation}\label{eq:closed-boundary}
   \boxed{
   \log\Delta(S_a-x)
   =
   -\frac1m\log|\det G|
   +
   \frac12
   \operatorname{Re}
   \operatorname{tr}_m\bigl(G\eta(G)\bigr).
   }
\end{equation}

\label{prop:action-identity}
Let $b\succ0$ and $U$ be unitary, and write
\begin{equation}\label{eq:normalized}
 M=b^{-1/2}Ub^{-1/2}=-u-i\gamma,
 \qquad u=u^*,\quad\gamma=\gamma^*.
\end{equation}
For every real $z$,
\begin{equation}\label{eq:K-action}
 \mathscr K_{z}(b,u,\gamma)
 =\operatorname{Re}\mathcal A_{z}(M) + \frac12.
\end{equation}

\label{lem:feasible-pf}
For every $b\succ0$, the normalized covariance map
$\widehat\eta_b$ has a nonzero positive semidefinite eigenmatrix
$P_b$ at its spectral radius:
\begin{equation}\label{eq:positive-Perron-eigenmatrix}
   \widehat\eta_b(P_b)=r_bP_b,
   \qquad
   P_b\succeq0,\quad P_b\ne0,
   \qquad
   r_b
   =
   \|\widehat\eta_b\|_{2\to2}
   =
   \lambda_{\max}(\widehat\eta_b).
\end{equation}
For $b\succ0$, the following are equivalent:
\begin{enumerate}
\item[(i)] $b\in\mathcal{F}$;
\item[(ii)] $\lambda_{\max}(\widehat\eta_b)\leq1$;
\item[(iii)] $\|\widehat\eta_b\|\leq1$;
\item[(iv)]
$L_b^- \succeq0$ 
   and
 $  L_b^+ \succeq0$ as Hilbert-Shmidt operators. 
\end{enumerate}
Moreover,
\begin{equation}\label{eq:interior-feasible}
   b\in\operatorname{int}\mathcal{F}
   \quad\Longleftrightarrow\quad
   \|\widehat\eta_b\|<1.
\end{equation}
In particular,
$L_b^- \succ 0$ and $L_b^+\succ0$ for $b\in\mathcal F^\circ$.

\label{prop:indicator}
For every $b\succ0$,
\begin{equation}\label{eq:indicator}
 \sup_{\gamma\succeq0}
 \left\{-\frac12\left\langle \gamma,L_b^-\gamma\right\rangle\right\}
 =\begin{cases}
   0,&b\in\mathcal{F},\\
   +\infty,&b\notin\mathcal{F}.
  \end{cases}
\end{equation}
Consequently,
\begin{equation}\label{eq:three-variable-real}
 \inf_{b\succ0}\sup_{\substack{u=u^*\\\gamma\succeq0}}
    \mathscr K_z(b,u,\gamma)
 =\inf_{b\in\mathcal{F}}F_z(b).
\end{equation}

\label{lem:geodesic-feasible}
Let $b_t=b_0\#_tb_1$.  Then
\begin{equation}\label{eq:eta-geodesic-logconvex}
   \|\widehat\eta_{b_t}\|
   \leq
   \|\widehat\eta_{b_0}\|^{1-t}
   \|\widehat\eta_{b_1}\|^t.
\end{equation}
Consequently, $\mathcal{F}$ is geodesically convex.  If
$b_0\in\mathcal{F}$ and $b_1\in\operatorname{int}\mathcal{F}$, then
\[
   b_t\in\operatorname{int}\mathcal{F}
   \qquad
   \text{for every }t\in(0,1].
\]

\label{lem:resolvent-geodesic}
Let $t\mapsto\mathcal C_t$ be a geodesic in $\operatorname{PD}(B)$,
and let $\Theta=\Theta^*$ be a fixed operator on $B$. Suppose
$L_t:=\mathcal C_t+\Theta\succ0$ throughout the interval under
consideration. Define
\begin{equation*}
   \widehat\Theta_t
   :=\mathcal C_t^{-1/2}\Theta\mathcal C_t^{-1/2},
   \qquad
   K_t:=\mathcal C_t^{-1/2}\mathcal C_t'L_t^{-1}.
\end{equation*}
Then
\begin{equation}\label{eq:resolvent-hessian}
   \frac{d^2}{dt^2}L_t^{-1}=K_t^*\Gamma_tK_t,
\end{equation}
where
\begin{equation}\label{eq:Cayley-factor}
   \Gamma_t
   :=(I-\widehat\Theta_t)(I+\widehat\Theta_t)^{-1}.
\end{equation}
In particular, at every $t$ for which $\Theta\preceq\mathcal C_t$,
\begin{equation*}
   \frac{d^2}{dt^2}L_t^{-1}\succeq0.
\end{equation*}
No positivity assumption on the fixed operator $\Theta$ is required.

Put $R_t:=L_t^{-1}$. Differentiating the inverse gives
\begin{equation*}
   R_t'=-R_t\mathcal C_t'R_t,
   \qquad
   R_t''=2R_t\mathcal C_t'R_t\mathcal C_t'R_t
            -R_t\mathcal C_t''R_t.
\end{equation*}
The geodesic equation
$\mathcal C_t''=\mathcal C_t'\mathcal C_t^{-1}\mathcal C_t'$
therefore yields
\begin{equation}\label{eq:resolvent-second-factor}
   R_t''
   =R_t\mathcal C_t'
      \bigl(2R_t-\mathcal C_t^{-1}\bigr)
      \mathcal C_t'R_t.
\end{equation}
Since
\begin{equation*}
   L_t=\mathcal C_t^{1/2}
           (I+\widehat\Theta_t)\mathcal C_t^{1/2},
\end{equation*}
we have
\begin{align}
   2L_t^{-1}-\mathcal C_t^{-1}
   &=\mathcal C_t^{-1/2}
       \bigl[2(I+\widehat\Theta_t)^{-1}-I\bigr]
       \mathcal C_t^{-1/2}\notag\\
   &=\mathcal C_t^{-1/2}
       (I-\widehat\Theta_t)(I+\widehat\Theta_t)^{-1}
       \mathcal C_t^{-1/2}.
   \label{eq:Cayley-factorization}
\end{align}
Substitution into \eqref{eq:resolvent-second-factor} proves
\eqref{eq:resolvent-hessian}.

The assumption $L_t\succ0$ implies $I+\widehat\Theta_t\succ0$.
If also $\Theta\preceq\mathcal C_t$, then
$I-\widehat\Theta_t\succeq0$. These two operators commute, since
both are functions of the self-adjoint operator $\widehat\Theta_t$.
Hence $\Gamma_t\succeq0$ by functional calculus, and
\eqref{eq:resolvent-hessian} gives the claimed inequality.

\label{cor:two-inverse-geodesic}
Let $b_t$ be a geodesic contained in
$\operatorname{int}\mathcal F$. Put
\begin{equation*}
   \mathcal C_t:=\mathcal C_{b_t},
   \qquad
   R_\pm(t):=(L_{b_t}^\pm)^{-1},
   \qquad
   K_\pm(t):=\mathcal C_t^{-1/2}\mathcal C_t'R_\pm(t).
\end{equation*}
Then, with
$\widehat\eta_t:=\mathcal C_t^{-1/2}\eta\mathcal C_t^{-1/2}
=\widehat\eta_{b_t}$,
\begin{equation}\label{eq:two-inverse-hessian}
   R_\pm''(t)
   =K_\pm(t)^*
      (I\mp\widehat\eta_t)(I\pm\widehat\eta_t)^{-1}
      K_\pm(t)
   \succeq0.
\end{equation}
Thus both $b\mapsto(L_b^+)^{-1}$ and $b\mapsto(L_b^-)^{-1}$
are geodesically convex in the L\"owner order on
$\operatorname{int}\mathcal F$. In particular, for every fixed
Hermitian matrix $v$, the following functions are geodesically convex there:
\begin{equation}\label{eq:two-inverse-quadratic}
   q_v^\pm(b):=\frac12
      \left\langle v,(L_b^\pm)^{-1}v\right\rangle.
\end{equation}

\label{prop:geodesic-hessian}
Let $b\in\operatorname{int}\mathcal F$, let $X=X^*$, and consider
$b_t=b^{1/2}e^{tX}b^{1/2}$ for $t$ sufficiently close to zero.
Set
\begin{equation*}
   u:=(L_b^+)^{-1}a_z,
   \qquad
   \widetilde u:=b^{1/2}ub^{1/2}.
\end{equation*}
Then
\begin{equation}\label{eq:geodesic-hessian}
   \boxed{
   \left.\frac{d^2}{dt^2}F_z(b_t)\right|_{t=0}
   =\frac12\left\langle
      X\widetilde u+\widetilde uX,\,
      (I-\widehat\eta_b)(I+\widehat\eta_b)^{-1}
      (X\widetilde u+\widetilde uX)
   \right\rangle.
   }
\end{equation}
In particular, this second derivative is nonnegative, and $F_z$
is geodesically convex on $\mathcal F$.

\label{def:unitary-normalizer}
Let $G\in M_m(\mathbb C)$ be invertible.  A matrix $b\succ0$ is called a
\textbf{unitary normalizer} of $G$ if
\begin{equation}\label{eq:unitary-normalizer}
   U:=b^{1/2}Gb^{1/2}
\end{equation}
is unitary.

\label{cor:balanced-dyson}
With the notation above,
\begin{align}
   (I+\widehat\eta_b)P
   &=
   -\widetilde a_{x,b},
   \label{eq:balanced-real}\\
   (I-\widehat\eta_b)Q
   &=
   \varepsilon b^{-1}.
   \label{eq:balanced-imag}
\end{align}

\label{prop:elimination}
Fix $z\in\mathbb R$ and $\varepsilon>0$. For $b\in\mathcal F^{\circ}$, the unique
maximizers in \eqref{eq:regularized-F-definition} are
\begin{equation}\label{eq:maximizers}
 u_b=(L_b^+)^{-1}a_z,
 \qquad
 \gamma_b=\varepsilon(L_b^-)^{-1}I\succ0.
\end{equation}
Their value is
\begin{equation}\label{eq:partial-sup}
\boxed{\begin{aligned}
 F_{z,\varepsilon}(b)
 ={}&\operatorname{tr}_m\log b
 +\frac12\left\langle a_z,(L_b^+)^{-1}a_z\right\rangle\\
 &+\frac{\varepsilon^2}{2}\left\langle I,(L_b^-)^{-1}I\right\rangle.
\end{aligned}}
\end{equation}
For $b\notin\mathcal F^{\circ}$, the supremum is $+\infty$. Thus $\mathcal F^{\circ}$ is
exactly the effective domain of $F_{z,\varepsilon}$.

\label{lem:Dyson-scale}
Fix $w=z+i\varepsilon$ with $\varepsilon>0$, and write
\begin{equation*}
 G_\varepsilon:=G(z+i\varepsilon)=-u_\varepsilon-i\gamma_\varepsilon,
 \qquad \gamma_\varepsilon\succ0.
\end{equation*}
Let $b_\varepsilon\succ0$ be the unitary normalizer of $G_\varepsilon$ given by
Lemma~\ref{lem:pup}.  It belongs to $\mathcal F^{\circ}$ and satisfies
\begin{equation}\label{eq:balanced}
\begin{aligned}
 L_{b_\varepsilon}^+u_\varepsilon&=a_z,\\
 L_{b_\varepsilon}^-\gamma_\varepsilon&=\varepsilonI,\\
 b_\varepsilon^{-1}&=u_\varepsilon b_\varepsilon u_\varepsilon
                  +\gamma_\varepsilon b_\varepsilon\gamma_\varepsilon.
\end{aligned}
\end{equation}
In particular, the maximizers from
Proposition~\ref{prop:elimination} at $b=b_\varepsilon$ are exactly
\begin{equation}\label{eq:Dyson-auxiliary-identification}
 u_{b_\varepsilon}=u_\varepsilon,
 \qquad \gamma_{b_\varepsilon}=\gamma_\varepsilon.
\end{equation}

\label{prop:regularized-first-variation}
For $b\in\mathcal F^{\circ}$, let $u_b$ and $\gamma_b$ be the maximizers in
\eqref{eq:maximizers}. For every Hermitian variation $h$,
\begin{equation}\label{eq:regularized-first-variation}
 DF_{z,\varepsilon}(b)[h]
 =\operatorname{tr}_m\!\left[
    \bigl(b^{-1}-u_bbu_b-\gamma_bb\gamma_b\bigr)h
   \right].
\end{equation}
Thus, with respect to the normalized Hilbert--Schmidt pairing,
\begin{equation}\label{eq:Freg-gradient}
 \boxed{
 \nabla F_{z,\varepsilon}(b)
 =b^{-1}-u_bbu_b-\gamma_bb\gamma_b.
 }
\end{equation}

Both shifted operators have the same differential:
\begin{equation*}
 D L_b^\pm[h](Y)=D\mathcal C_{b}[h](Y)=hYb+bYh.
\end{equation*}
Using
$D(L_b^\pm)^{-1}[h]=-(L_b^\pm)^{-1}D\mathcal C_{b}[h](L_b^\pm)^{-1}$
in \eqref{eq:partial-sup}, and the definitions of $u_b$ and
$\gamma_b$, gives
\begin{equation*}
\begin{split}
 DF_{z,\varepsilon}(b)[h]
 ={}&\operatorname{tr}_m(b^{-1}h)
   -\frac12\left\langle u_b,hu_bb+bu_bh\right\rangle\\
   &-\frac12\left\langle \gamma_b,h\gamma_bb+b\gamma_bh\right\rangle.
\end{split}
\end{equation*}
For every Hermitian $v$, cyclicity of the trace gives
$\frac12\left\langle v,hvb+bvh\right\rangle=\operatorname{tr}_m(vbv h)$.
Apply this once with $v=u_b$ and once with $v=\gamma_b$ to obtain
\eqref{eq:regularized-first-variation}.

\label{cor:Freg-convex}
For every $z\in\mathbb R$ and $\varepsilon>0$, $F_{z,\varepsilon}$ is
geodesically convex on the geodesically convex set $\mathcal F^{\circ}$.

\label{thm:regularized}
For every $z\in\mathbb R$ and $\varepsilon>0$,
\begin{equation}\label{eq:regularized-theorem}
 \boxed{
 \log\Delta(S_a-z-i\varepsilon)
 =-\frac12+\min_{b\in\mathcal F^{\circ}}F_{z,\varepsilon}(b).
 }
\end{equation}
The minimum is attained at the scale $b_\varepsilon$ from
Lemma~\ref{lem:Dyson-scale}. Equivalently,
\begin{equation}\label{eq:full-regularized}
 \log\Delta(S_a-z-i\varepsilon)
 =-\frac12+\min_{b\succ0}
    \sup_{\substack{u=u^*\\\gamma\succeq0}}
       \mathcal{K}_{z,\varepsilon}(b,u,\gamma).
\end{equation}

\textbf{Identification of the maximizing variables and stationarity.}
At the Dyson scale, the first two balanced equations give explicitly
\begin{equation*}
 u_{b_\varepsilon}=(L_{b_\varepsilon}^+)^{-1}a_z=u_\varepsilon,
 \qquad
 \gamma_{b_\varepsilon}=\varepsilon(L_{b_\varepsilon}^-)^{-1}I=\gamma_\varepsilon.
\end{equation*}
Substituting these identities into the gradient formula yields
\begin{equation*}
\begin{aligned}
 \nabla F_{z,\varepsilon}(b_\varepsilon)
 &=b_\varepsilon^{-1}-u_\varepsilon b_\varepsilon u_\varepsilon
                    -\gamma_\varepsilon b_\varepsilon\gamma_\varepsilon\\
 &=\underbrace{\bigl(b_\varepsilon^{-1}-u_\varepsilon b_\varepsilon u_\varepsilon\bigr)}
      _{\displaystyle=\,\gamma_\varepsilon b_\varepsilon\gamma_\varepsilon}
      -\gamma_\varepsilon b_\varepsilon\gamma_\varepsilon
 =0.
\end{aligned}
\end{equation*}
Here the underbraced equality is exactly the third balanced equation.
Thus the first two equations identify the inner maximizers, while the
third makes their reduced objective stationary in $b$.

\textbf{Global minimality.}
Fix $c\in\mathcal F^{\circ}$ and take the geodesic
\begin{equation*}
 b_t=b_\varepsilon^{1/2}e^{tX}b_\varepsilon^{1/2},
 \qquad
 X=\log(b_\varepsilon^{-1/2}cb_\varepsilon^{-1/2}),\quad 0\leq t\leq1.
\end{equation*}
It lies in $\mathcal F^{\circ}$. The function $f(t)=F_{z,\varepsilon}(b_t)$ is convex
by Corollary~\ref{cor:Freg-convex}, and $f'(0)=0$ by stationarity.
Therefore $F_{z,\varepsilon}(c)=f(1)\geq f(0)=F_{z,\varepsilon}(b_\varepsilon)$.
This proves global minimality without requiring compactness of a
minimizing sequence.

\textbf{Value at the minimum.}
Write $G=G(z+i\varepsilon)=-u_\varepsilon-i\gamma_\varepsilon$.
At the identified maximizers, the explicit formula for the objective
becomes
\begin{equation*}
 F_{z,\varepsilon}(b_\varepsilon)
 =\operatorname{tr}_m\log b_\varepsilon
   +\frac12\left\langle a_z,u_\varepsilon\right\rangle
   +\frac{\varepsilon}{2}\operatorname{tr}_m\gamma_\varepsilon.
\end{equation*}
Multiplying the Dyson equation by $G$, taking the normalized trace,
and then taking real parts gives
\begin{equation*}
 \left\langle a_z,u_\varepsilon\right\rangle+\varepsilon\operatorname{tr}_m\gamma_\varepsilon
 =1+\operatorname{Re}\operatorname{tr}_m\bigl(G\eta(G)\bigr).
\end{equation*}
Also, unitarity of $b_\varepsilon^{1/2}Gb_\varepsilon^{1/2}$ implies
$\operatorname{tr}_m\log b_\varepsilon=-m^{-1}\log|\det G|$. Consequently,
\begin{equation*}
\begin{aligned}
 F_{z,\varepsilon}(b_\varepsilon)-\frac12
 &=-\frac1m\log|\det G|
    +\frac12\operatorname{Re}\operatorname{tr}_m\bigl(G\eta(G)\bigr)\\
 &=\log\Delta(S_a-z-i\varepsilon),
\end{aligned}
\end{equation*}
where the last equality is the closed determinant identity of
Theorem~\ref{thm:closed}. This proves
\eqref{eq:regularized-theorem}.
Finally, $F_{z,\varepsilon}=\sup_{u,\gamma}\mathcal{K}_{z,\varepsilon}$ by definition,
and Proposition~\ref{prop:elimination} makes this supremum infinite
off $\mathcal F^{\circ}$. This proves \eqref{eq:full-regularized}.

\label{thm:real-axis}
For every $z\in\mathbb{R}$,
\begin{equation}\label{eq:real-theorem}
 \boxed{
 \log\Delta(S_a-z)
 =-\frac12+\inf_{b\in\mathcal{F}}F_z(b)
 }
\end{equation}
in $[-\infty,\infty)$.

\label{thm:centered-capacity}
For every self-adjoint completely positive covariance map $\eta$,
\begin{equation}\label{eq:centered-capacity}
   \boxed{
   \inf_{b\in\mathcal{F}}\Delta(b)
   =
   \operatorname{Cap}(\eta)^{1/(2m)}.
   }
\end{equation}

Moreover, the infimum in \eqref{eq:centered-capacity} is attained if and
only if $\eta$ is symmetrically doubly-stochastic scalable; equivalently,
if and only if there exists $C\succ0$ such that
\begin{equation}\label{eq:symmetric-DS}
   \eta(C)=C^{-1}.
\end{equation}
If such $C$ exists, an optimizer is
$
   b=C^{-1}.
$

\label{cor:mai-speicher}
For the centered matrix semicircle
\[
   S_0
   =
   \sum_{j=1}^r A_j\otimes s_j,
\]
one has
\begin{equation}\label{eq:mai-speicher}
   \boxed{
   \log\Delta(S_0)
   =
   -\frac12
   +
   \frac1{2m}
   \log\operatorname{Cap}(\eta).
   }
\end{equation}
The identity is understood in the extended-real sense when
$\operatorname{Cap}(\eta)=0$.

\label{ques:other-families}
Is there a variational formula analogous to \eqref{eq:intro-main-formula}
for $a\otimes1+\sum_ia_i\otimes u_i$ with free Haar unitaries $u_i$, or
more generally for operator-valued free variables whose $R$-transform is a
polynomial in the operator-valued sense?

\label{lem:theta-one-atom}
For $x\in\mathbb R$,
\begin{equation}\label{eq:theta-one-iff-atom}
   \theta(x)=1
   \quad\Longleftrightarrow\quad
   \mu_{S_a}(\{x\})>0.
\end{equation}
